"geojson-import" |
// GeoJSON export: the written GeoJSON file.
"geojson-export" |
// Canvas PDF export.
"pdf-export" |
// Budget › Export as CSV.
"budget-csv-export" |
// Data library › Import: one or more GeoTIFF files.
"lidar-geotiff-import";

